import numpy as np
from scipy.optimize import minimize

def solve_n(n):
    # Objective: maximize sum(a_i * a_{i+2})
    # Constraints: a_i + a_{i+1} + a_{i+2} <= 2
    # a_i >= 0

    def objective(a):
        s = 0
        for i in range(n):
            s += a[i] * a[(i+2) % n]
        return -s

    cons = []
    for i in range(n):
        def con(a, i=i):
            return 2 - (a[i] + a[(i+1)%n] + a[(i+2)%n])
        cons.append({'type': 'ineq', 'fun': con})

    bounds = [(0, 2)] * n

    # Try different starting points
    best_s = -1
    for start_a in [np.full(n, 2/3), np.array([1,0,1,0]* (n//4+1))[:n], np.random.rand(n)]:
        res = minimize(objective, start_a, bounds=bounds, constraints=cons)
        if res.success and -res.fun > best_s:
            best_s = -res.fun
    return best_s

results = {n: solve_n(n) for n in range(3, 13)}
print(results)
